func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"lowercases", "Ada Lovelace", "ada-lovelace"},
		{"case insensitive", "ADA", "ada"},
		{"folds whitespace runs", "Ada   Lovelace", "ada-lovelace"},
		{"trims leading and trailing", "  Ada Lovelace  ", "ada-lovelace"},
		{"mixed whitespace", "Ada\tLovelace\nByron", "ada-lovelace-byron"},
		{"already slug", "ada-lovelace", "ada-lovelace"},
		{"single word", "Ada", "ada"},
		{"empty", "", ""},
		{"whitespace only", "   ", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}
