package greeter

import "strings"

// Slug 把名字转成适合做页面锚点的 URL 友好 slug：
// 转小写（大小写不敏感）、空白折成连字符、首尾不留。
func Slug(name string) string {
	return strings.ToLower(strings.Join(strings.Fields(name), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"single word lowercased", "Ada", "ada"},
		{"space becomes hyphen", "Ada Lovelace", "ada-lovelace"},
		{"case insensitive", "ADA LOVELACE", "ada-lovelace"},
		{"whitespace runs collapse", "Ada   Lovelace", "ada-lovelace"},
		{"leading and trailing trimmed", "  Ada Lovelace  ", "ada-lovelace"},
		{"mixed whitespace", "Ada\tLovelace\nByron", "ada-lovelace-byron"},
		{"already a slug", "ada-lovelace", "ada-lovelace"},
		{"empty", "", ""},
		{"whitespace only", "   ", ""},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Slug(tt.in); got != tt.want {
				t.Fatalf("Slug(%q) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

func TestSlugIsCaseInsensitive(t *testing.T) {
	if Slug("Ada Lovelace") != Slug("ada lovelace") {
		t.Fatal("Slug should be case insensitive")
	}
}
